import { atlasesOf, effectNames, idleAtlasOf, portraitOf, urlsOf } from '../strip-urls';
import type { Atlas, FighterArt } from '../types';
import { KODA_CELLS } from './cells';
import { KODA_CLIPS, KODA_PROJECTILES } from './clips';
import { KODA_SHEETS } from './sheets';

/** Strips generated by `npm run sprites` (tools/sprites), one folder per colorway. */
const MAIN = import.meta.glob<string>('./main/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT = import.meta.glob<string>('./alt/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
/** Front effects of the strips that have some (energy, flashes, speed lines). */
const MAIN_FX = import.meta.glob<string>('./main/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT_FX = import.meta.glob<string>('./alt/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});

const MAIN_ATLASES = import.meta.glob<string>('./main/**/*.json', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT_ATLASES = import.meta.glob<string>('./alt/**/*.json', {
  eager: true,
  query: '?url',
  import: 'default',
});
const IDLE_ATLASES = import.meta.glob<Atlas>('./*/idle.json', { eager: true, import: 'default' });

const SHARED = {
  portrait: { x: 30, y: 0, size: 56 },
  sheets: KODA_SHEETS,
  clips: KODA_CLIPS,
  projectiles: KODA_PROJECTILES,
  cells: KODA_CELLS,
  ownLight: true,
};

/** Storm-teal frock coat, spiky emerald-green hair, silver armor, jade acoustic energy. */
export const KODA: FighterArt = {
  key: 'koda',
  urls: urlsOf(MAIN, 'main', KODA_SHEETS),
  fx: urlsOf(MAIN_FX, 'main/fx', effectNames(KODA_SHEETS, KODA_CLIPS)),
  atlases: atlasesOf(MAIN_ATLASES, 'main', KODA_SHEETS, effectNames(KODA_SHEETS, KODA_CLIPS)),
  ...idleAtlasOf(IDLE_ATLASES, 'main', KODA_CLIPS.idle.sheet),
  ...portraitOf(MAIN, 'main'),
  ...SHARED,
};
/** Deep plum frock coat, platinum-silver hair, amethyst acoustic energy: player 2 in a mirror match. */
export const KODA_ALT: FighterArt = {
  key: 'koda-alt',
  urls: urlsOf(ALT, 'alt', KODA_SHEETS),
  fx: urlsOf(ALT_FX, 'alt/fx', effectNames(KODA_SHEETS, KODA_CLIPS)),
  atlases: atlasesOf(ALT_ATLASES, 'alt', KODA_SHEETS, effectNames(KODA_SHEETS, KODA_CLIPS)),
  ...idleAtlasOf(IDLE_ATLASES, 'alt', KODA_CLIPS.idle.sheet),
  ...portraitOf(ALT, 'alt'),
  ...SHARED,
};
